const MAN=W.ACH_EN_MAN||{};const caricate={},attese={};
function caricaMem(chiave){
  const n=chiave==="note"?MAN.note:null;if(!n||caricate[chiave])return attese[chiave]||Promise.resolve();
  caricate[chiave]=1;
  return attese[chiave]=fetch(n).then(r=>r.ok?r.json():null).then(j=>{if(!j)return;for(const k in j)MEM.set(k,j[k]);CACHE.clear();
    requestAnimationFrame(()=>giroTutto());}).catch(()=>{});
}
/* ricerca in inglese: la pagina legge la casella di ricerca gia' tradotta in italiano (castle -> castell, Florence -> firenze);
   chi guarda continua a vedere le parole che ha scritto */
const QF=[["old town","centro storico"],["historic centre","centro storico"],["historic center","centro storico"],["aosta valley","valle d'aosta"],["south tyrol","alto adige"],["leaning tower","torre pendente"]];
const QC={rome:"roma",florence:"firenze",venice:"venezia",naples:"napoli",milan:"milano",turin:"torino",genoa:"genova",padua:"padova",mantua:"mantova",syracuse:"siracusa",tuscany:"toscana",sicily:"sicilia",sardinia:"sardegna",lombardy:"lombardia",piedmont:"piemonte",apulia:"puglia",leghorn:"livorno",the:"",of:"",and:"",a:"",in:""};
const QS=[["seafood","pesce"],["fish","pesce"],["pizzeria","pizzeri"],["pizza","pizz"],["trattoria","trattori"],["tavern","osteri"],["inn","locand"],["restaurant","ristorant"],["meat","carne"],["grill","grigli"],["steak","bistecc"],["vegetarian","vegetarian"],["vegan","vegan"],["japanese","giappon"],["sushi","sushi"],["chinese","cines"],["historic","storic"],["bakery","forn"],["cellar","cantin"],["amphitheat","anfiteatr"],["castle","castell"],["fortress","fortezz"],["fort","fort"],["tower","torr"],["wall","mura"],["palace","palazz"],["square","piazz"],["church","chies"],["cathedral","duomo"],["basilica","basilic"],["abbey","abbazi"],["monaster","monaster"],["convent","convent"],["sanctuar","santuari"],["chapel","cappell"],["baptist","battister"],["museum","muse"],["galler","galleri"],["painting","pittur"],["archaeolog","archeolog"],["archeolog","archeolog"],["ruin","rovin"],["roman","roman"],["etruscan","etrusc"],["greek","grec"],["mediev","mediev"],["theat","teatr"],["bridge","ponte"],["fountain","fontan"],["garden","giardin"],["botanic","botanic"],["park","parc"],["reserve","riserv"],["lake","lag"],["river","fium"],["waterfall","cascat"],["beach","spiagg"],["sea","mare"],["island","isol"],["mountain","mont"],["volcan","vulcan"],["cave","grott"],["trail","sentier"],["path","sentier"],["hik","sentier"],["view","panoram"],["panoram","panoram"],["village","borg"],["market","mercat"],["spa","term"],["thermal","term"],["cemeter","cimiter"],["lighthouse","faro"],["harbo","port"],["library","bibliotec"],["science","scienz"],["universit","universit"],["wine","vin"],["cheese","formagg"],["mosaic","mosaic"],["fresco","affresc"],["synagog","sinagog"],["villa","vill"],["gate","porta"],["arch","arco"],["column","colonn"],["temple","tempi"],["necropol","necropol"],["tomb","tomb"],["catacomb","catacomb"]];
function qIt(v){if(!v)return v;let s=" "+v.toLowerCase()+" ";for(const [a,b] of QF)s=s.split(" "+a+" ").join(" "+b+" ");
  return s.trim().split(/\s+/).map(w=>{if(w in QC)return QC[w];for(const [a,b] of QS)if(w.startsWith(a))return b;return w;}).filter(Boolean).join(" ");}
function ricercaInglese(el){if(!el||el.__en)return;el.__en=1;const P=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,"value");
  try{Object.defineProperty(el,"value",{configurable:true,get(){return qIt(P.get.call(this));},set(x){P.set.call(this,x);}});}catch(e){}}
function cercaCaselle(){for(const id of ["q","mq","qs","luogo","pv-q"])ricercaInglese(document.getElementById(id));for(const e of document.querySelectorAll('input[type="search"]'))ricercaInglese(e);}
W.ACH_EN={tr,giro,carica:caricaMem,enk,MEM,D,qIt};
W.ENL=s=>tr(s);
